#!/usr/bin/env bash
# shellcheck disable=SC2015  # pass/fail never fail, so `A && pass || fail` is an if-then-else here
# tailwind-css_test.sh — the console stylesheet generator refuses a Tailwind
# CLI whose checksum does not match its pin, and never runs it.
#
# GitHub #165: the console loaded the Tailwind Play CDN from a third party; it
# now uses a stylesheet generated by a pinned CLI (web-ui-design.md
# "Self-hosted Tailwind and the console CSP"). The pin is only a control if a
# swapped binary is refused, so that is what these cases pin. No network: the
# binary comes from $TAILWINDCSS_BIN, and the empty cache directory is never
# fetched into because $TAILWINDCSS_BIN takes precedence.
set -uo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
fails=0
pass() { echo "ok   $1"; }
fail() { echo "FAIL $1"; fails=$((fails + 1)); }

# A stand-in CLI that records that it ran.
cat > "$TMP/fake-tailwind" <<STUB
#!/usr/bin/env bash
touch "$TMP/ran"
exit 0
STUB
chmod +x "$TMP/fake-tailwind"
before=$(sha256sum "$ROOT/internal/ui/static/tailwind.css" 2>/dev/null || shasum -a 256 "$ROOT/internal/ui/static/tailwind.css")

# 1. Generate mode with a binary that does not match the pin: refused, not run,
#    and the committed stylesheet is untouched.
out=$(TAILWINDCSS_BIN="$TMP/fake-tailwind" XDG_CACHE_HOME="$TMP/cache" "$ROOT/scripts/tailwind-css.sh" 2>&1); rc=$?
[ "$rc" -ne 0 ] && pass "a mismatched CLI fails generate (rc=$rc)" || fail "a mismatched CLI was accepted: $out"
[ ! -e "$TMP/ran" ] && pass "the mismatched CLI was never executed" || fail "the mismatched CLI ran"
case "$out" in *"Refusing to run it"*) pass "the refusal names itself" ;; *) fail "unexpected refusal text: $out" ;; esac
after=$(sha256sum "$ROOT/internal/ui/static/tailwind.css" 2>/dev/null || shasum -a 256 "$ROOT/internal/ui/static/tailwind.css")
[ "$before" = "$after" ] && pass "the committed stylesheet is untouched" || fail "the committed stylesheet changed"

# 2. Check mode refuses the same way (the generate-check must not pass on an
#    unverified binary).
rm -f "$TMP/ran"
TAILWINDCSS_BIN="$TMP/fake-tailwind" XDG_CACHE_HOME="$TMP/cache" "$ROOT/scripts/tailwind-css.sh" --check >/dev/null 2>&1; rc=$?
[ "$rc" -ne 0 ] && [ ! -e "$TMP/ran" ] && pass "a mismatched CLI fails --check without running" || fail "--check rc=$rc ran=$([ -e "$TMP/ran" ] && echo yes || echo no)"

# 3. A missing binary is a failure, not a skip.
TAILWINDCSS_BIN="$TMP/absent" XDG_CACHE_HOME="$TMP/cache" "$ROOT/scripts/tailwind-css.sh" --check >/dev/null 2>&1; rc=$?
[ "$rc" -ne 0 ] && pass "a missing CLI fails --check" || fail "a missing CLI passed --check"

# 4. An unknown argument is a usage error.
"$ROOT/scripts/tailwind-css.sh" --bogus >/dev/null 2>&1; rc=$?
[ "$rc" -eq 2 ] && pass "an unknown argument is a usage error" || fail "unknown argument rc=$rc"

[ "$fails" -eq 0 ] || { echo "tailwind-css_test: $fails failure(s)"; exit 1; }
echo "tailwind-css_test: all passed"
